import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';import '../models/available_slot.dart';import '../repositories/dashboard_repository.dart';
class BookingScreen extends StatelessWidget{const BookingScreen({required this.shopId,super.key});final String shopId;@override Widget build(BuildContext context){final db=FirebaseFirestore.instance;return Scaffold(appBar:AppBar(title:const Text('CancelWait 予約')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection('shops').doc(shopId).collection('availableSlots').where('status',isEqualTo:'open').snapshots(),builder:(context,snapshot){if(snapshot.hasError)return Center(child:Text('空き枠を読み込めませんでした: ${snapshot.error}'));if(!snapshot.hasData)return const Center(child:CircularProgressIndicator());final slots=snapshot.data!.docs.map(AvailableSlot.fromDocument).where((s)=>!s.isPast&&s.remainingCapacity>0).toList()..sort((a,b)=>a.startAt.compareTo(b.startAt));return FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(future:db.collection('shops').doc(shopId).get(),builder:(context,shop){final name=shop.data?.data()?['name']??'店舗';return ListView(padding:const EdgeInsets.all(20),children:[Text('$name の空き枠',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('ご希望の時間を選び、先着順で予約を確定してください。'),const SizedBox(height:24),if(slots.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(40),child:Center(child:Text('現在予約できる空き枠はありません。')))),...slots.map((s)=>Padding(padding:const EdgeInsets.only(bottom:12),child:Card(child:ListTile(contentPadding:const EdgeInsets.all(18),title:Text('${s.startAt.year}/${s.startAt.month}/${s.startAt.day} ${_t(s.startAt)}〜${_t(s.endAt)}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${s.menuName} ・ 担当 ${s.staffName} ・ 残り${s.remainingCapacity}名'),trailing:FilledButton(onPressed:()=>_reserve(context,s),child:const Text('予約する')))))]);});}));}
static String _t(DateTime d)=>'${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';Future<void> _reserve(BuildContext context,AvailableSlot slot)async{final key=GlobalKey<FormState>(),name=TextEditingController(),phone=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(context)=>AlertDialog(title:const Text('予約者情報'),content:Form(key:key,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'お名前'),validator:(v)=>v==null||v.trim().isEmpty?'入力してください':null),const SizedBox(height:12),TextFormField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'電話番号'),validator:(v)=>v==null||v.trim().length<8?'正しい電話番号を入力してください':null)])),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('キャンセル')),FilledButton(onPressed:(){if(key.currentState!.validate())Navigator.pop(context,true);},child:const Text('予約を確定'))]));if(ok==true){try{await FirestoreDashboardRepository(FirebaseFirestore.instance).reserve(shopId,slot,name:name.text,phone:phone.text);if(context.mounted)showDialog<void>(context:context,builder:(_)=>AlertDialog(title:const Text('予約が確定しました'),content:const Text('ご予約ありがとうございます。'),actions:[FilledButton(onPressed:()=>Navigator.pop(context),child:const Text('閉じる'))]));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}name.dispose();phone.dispose();}}
